// Open a GeoPackage tile table as one image.
export function mosaicOf(matrixSet, matrix, contents) {
  const width = matrix.matrixWidth * matrix.tileWidth;
  const height = matrix.matrixHeight * matrix.tileHeight;
  const bounds = [matrixSet.minX, matrixSet.minY, matrixSet.maxX, matrixSet.maxY];
  const pixelX = (bounds[2] - bounds[0]) / width;
  const pixelY = (bounds[3] - bounds[1]) / height;
  return { width, height, bounds, pixelX, pixelY, srs: contents.srsId };
}
